 [STAThread]static int Main(){Application.EnableVisualStyles();var d=Store.Load();d.Games=new List<GameEntry>();d.Collections=new List<GameCollection>();d.Emulators=new List<EmulatorProfile>();d.PlaySessions=new List<PlaySession>();d.PlayQueue=new List<string>();d.SmartLists=new List<SmartLibraryList>();d.UserTools=null;NextData.Ensure(d);LibraryAdditions.Ensure(d);
