  using(var f=new Form{Width=700,Height=400,ShowInTaskbar=false,StartPosition=FormStartPosition.Manual,Location=new Point(-3000,-3000)}){var list=new ListBox{Top=10,Width=250,Height=100};list.Items.AddRange(new object[]{"one","two","three"});list.SelectedIndex=0;int activated=0;list.DoubleClick+=(a,b)=>activated++;var button=new Button{Text="Action",Top=150};int clicked=0;button.Click+=(a,b)=>clicked++;f.Controls.Add(list);f.Controls.Add(button);f.Show();list.Focus();UserToolRuntime.ApplyButtons(f,f,2);Check(list.SelectedIndex==1,"controller navigates selected list item");UserToolRuntime.ApplyButtons(f,f,0x1000);Check(activated==1,"controller activates selected item");button.Focus();UserToolRuntime.ApplyButtons(f,f,0x1000);Check(clicked==1,"controller activates focused button");UserToolRuntime.ApplyButtons(f,f,0x2000);Check(!f.IsDisposed,"controller B preserves main window");}
  using(var owner=new Form{ShowInTaskbar=false,StartPosition=FormStartPosition.Manual,Location=new Point(-3000,-3000)}){owner.Show();using(var timer=new System.Windows.Forms.Timer{Interval=400}){timer.Tick+=(a,b)=>{var f=Application.OpenForms.Cast<Form>().OfType<NextDialog>().FirstOrDefault(x=>x.Text=="User tools");if(f==null)return;timer.Stop();var tabs=NextUi.Descendants(f).OfType<TabControl>().Single();Check(tabs.TabPages.Count==3,"new tools use three grouped tabs");foreach(TabPage tab in tabs.TabPages){tabs.SelectedTab=tab;Application.DoEvents();Check(tab.AutoScroll,"tool tabs can scroll");using(var bmp=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bmp,new Rectangle(0,0,bmp.Width,bmp.Height));bmp.Save("user-tools-"+tab.Text.Replace(" ","-")+".png");}}f.Close();};timer.Start();UserTools.Show(owner,d,()=>{});}}
  using(var art=new Bitmap(40,30)){art.Save("art.png",System.Drawing.Imaging.ImageFormat.Png);}g.ArtworkPath=Path.GetFullPath("art.png");Check(UserTools.Html(d.Games,false,false,true).Contains("data:image/png;base64,"),"artwork embedded as offline thumbnail");Check(!UserTools.Html(d.Games,false,false,true).Contains(g.ArtworkPath),"artwork source path stays private");Check(!UserTools.Html(d.Games,false,false).Contains("data:image"),"artwork excluded unless selected");Throws(()=>UserTools.Html(d.Games,false,false,true,cancel.Token),"catalog rendering cancellation");
  var reference=d.Games[0];saved=File.ReadAllText(Store.FileName);using(var owner=new Form{ShowInTaskbar=false,StartPosition=FormStartPosition.Manual,Location=new Point(-3000,-3000)}){owner.Show();using(var timer=new System.Windows.Forms.Timer{Interval=300}){int phase=0;timer.Tick+=(a,b)=>{if(phase==0){var f=Application.OpenForms.Cast<Form>().OfType<NextDialog>().FirstOrDefault(x=>x.Text=="User tools");if(f==null)return;phase=1;NextUi.Descendants(f).OfType<Button>().Single(x=>x.Text=="Guest browser").PerformClick();}else{var guest=Application.OpenForms.Cast<Form>().OfType<NextDialog>().FirstOrDefault(x=>x.Text.StartsWith("Guest browser"));if(guest==null)return;timer.Stop();Check(UserTools.Guest,"guest UI enables persistence guard");Check(!NextUi.Descendants(guest).OfType<Button>().Any(x=>x.Text.Contains("Edit")||x.Text.Contains("Remove")),"guest UI has no editing commands");var input=NextUi.Descendants(guest).OfType<TextBox>().Single();input.Text="no match anywhere";Check(NextUi.Descendants(guest).OfType<ListBox>().Single().Items.Count==0,"guest library filter works");Store.Save(d);guest.Close();}};timer.Start();UserTools.Show(owner,d,()=>{});}}Check(!UserTools.Guest&&object.ReferenceEquals(reference,d.Games[0]),"guest UI leaves live game references intact");Check(File.ReadAllText(Store.FileName)==saved,"guest UI makes no library writes");
  Console.WriteLine("PASS: "+checks+" user-tool checks covering profiles, guest persistence, undo conflicts, catalog privacy, DAT checksums and controller actions.");return 0;
